    @add("prior_f06_partial_child_create_rolls_back_or_types_failure")
    def _() -> None:
        transport = object.__new__(s.DescriptorCgroupTransport)
        transport.mount = "/unused"
        parent = SimpleNamespace(fd=42)
        with ExitStack() as stack:
