    @add("descriptor_allowlisted_partial_write_loop")
    def _() -> None:
        read_fd, write_fd = os.pipe()
        try:
            original = os.write
            first = True
            def partial(fd: int, payload: bytes) -> int:
                nonlocal first
                if first:
                    first = False
                    return original(fd, payload[:1])
